def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    pts=[(i,j) for i in range(h) for j in range(w) if g[i][j]==2]
    def fill_between(a,b):
        (r1,c1),(r2,c2)=a,b
        if r1==r2:
            for j in range(min(c1,c2)+1,max(c1,c2)): out[r1][j]=3
        elif c1==c2:
            for i in range(min(r1,r2)+1,max(r1,r2)): out[i][c1]=3
    # 1) connect aligned pairs
    for x in range(len(pts)):
        for y in range(x+1,len(pts)):
            if pts[x][0]==pts[y][0] or pts[x][1]==pts[y][1]:
                fill_between(pts[x],pts[y])
    # 2) each unconnected 2 extends along row/col to nearest structure cell
    def struct_cells():
        return {(i,j) for i in range(h) for j in range(w) if out[i][j]==3}
    for (r,c) in pts:
        cells=struct_cells()
        # already adjacent to a line?
        if any((r+dr,c+dc) in cells for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))): continue
        colc=[(abs(i-r),(i,c)) for i in range(h) if out[i][c]==3 and i!=r]
        rowc=[(abs(j-c),(r,j)) for j in range(w) if out[r][j]==3 and j!=c]
        cand=colc+rowc
        if not cand: continue
        dist,(tr,tc)=min(cand)
        # fill from marker toward target, stopping adjacent to it
        if tr==r:
            lo,hi=min(c,tc),max(c,tc)
            for j in range(lo,hi+1):
                if out[r][j]==0: out[r][j]=3
        else:
            lo,hi=min(r,tr),max(r,tr)
            for i in range(lo,hi+1):
                if out[i][c]==0: out[i][c]=3
    return out

