def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    pts=[(i,j) for i in range(h) for j in range(w) if g[i][j]==2]
    def span(a,b):
        (r1,c1),(r2,c2)=a,b
        if r1==r2: return [(r1,j) for j in range(min(c1,c2),max(c1,c2)+1)]
        if c1==c2: return [(i,c1) for i in range(min(r1,r2),max(r1,r2)+1)]
        return []
    trunk=set()
    for x in range(len(pts)):
        for y in range(x+1,len(pts)):
            s=span(pts[x],pts[y])
            if s:
                for cell in s:
                    if out[cell[0]][cell[1]]==0: out[cell[0]][cell[1]]=3
                trunk.update(s)
    for (r,c) in pts:
        if (r,c) in trunk: continue
        cand=[(abs(i-r),(i,c)) for i in range(h) if (i,c) in trunk and i!=r]
        cand+=[(abs(j-c),(r,j)) for j in range(w) if (r,j) in trunk and j!=c]
        if not cand: continue
        _,(tr,tc)=min(cand)
        for (i,j) in span((r,c),(tr,tc)):
            if out[i][j]==0: out[i][j]=3
    return out

